    Real inverseSr=pow(field, 3)/p.eta + pow(field, roughnessExponent)/p.delta;
    Real inverseSr_d0=c29_1*q.roughnessExponent.derivative[0] + c29_2*field_d0;
    Real inverseSr_d1=c29_1*q.roughnessExponent.derivative[1] + c29_2*field_d1;
    Real inverseSr_d2=c29_1*q.roughnessExponent.derivative[2] + c29_2*field_d2;
    Real inverseSr_d3=c29_1*q.roughnessExponent.derivative[3] + c29_2*field_d3;
    Real inverseSr_d4=c29_1*q.roughnessExponent.derivative[4] + c29_2*field_d4;
    Real inverseSr_d5=c29_1*q.roughnessExponent.derivative[5] + c29_2*field_d5;
    Real inverseSr_d6=c29_1*q.roughnessExponent.derivative[6] + c29_2*field_d6;
