    const Real c31_1=roughnessNumerator/pow(inverseSr, 2);
    muSr=roughnessNumerator/inverseSr;
    muSr_d0=c31_0*q.roughnessNumerator.derivative[0] - c31_1*inverseSr_d0;
    muSr_d1=c31_0*q.roughnessNumerator.derivative[1] - c31_1*inverseSr_d1;
    muSr_d2=c31_0*q.roughnessNumerator.derivative[2] - c31_1*inverseSr_d2;
    muSr_d3=c31_0*q.roughnessNumerator.derivative[3] - c31_1*inverseSr_d3;
    muSr_d4=c31_0*q.roughnessNumerator.derivative[4] - c31_1*inverseSr_d4;
