    invPh_d0=-c39_0*muPh_d0;
    invPh_d1=-c39_0*muPh_d1;
    invPh_d2=-c39_0*muPh_d2;
    invPh_d3=-c39_0*muPh_d3;
    invPh_d4=-c39_0*muPh_d4;
